jQuery(function($){"use strict";const header=document.querySelector('.header_wrap');const menuArea=document.querySelector('.bh .main_menu > ul');const dropdowns=document.querySelectorAll('.bh .main_menu .menu_dropdown-content');let showTimer=null;dropdowns.forEach(dd=>dd.style.display="none");menuArea.addEventListener("mouseenter",()=>{if(showTimer)clearTimeout(showTimer);header.classList.add("menu-open");showTimer=setTimeout(()=>{header.classList.add("menu-open");dropdowns.forEach(dd=>dd.style.display="block")},300)});header.addEventListener("mouseleave",()=>{if(showTimer)clearTimeout(showTimer);dropdowns.forEach(dd=>dd.style.display="none");header.classList.remove("menu-open")})})